WITH session_totals AS (SELECT session_id, COUNT(CASE WHEN page = '/checkout' THEN 1 END) AS checkout_count, COUNT(CASE WHEN page = '/search' THEN 1 END) AS search_count FROM web_events WHERE session_id IN (31, 36) GROUP BY session_id) SELECT s.started_at, st.checkout_count, st.search_count FROM sessions s INNER JOIN session_totals st ON s.id = st.session_id ORDER BY st.checkout_count;
